/* ASCII Setup — SaaS dark editor theme, red accent (Inter type comes from tracery-font.css). */
.ascii-window {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0; z-index: 1000;
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: #f0e8e8; font-size: 13px;
  animation: ascii-in 0.22s ease-out;
}
@keyframes ascii-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
.ascii-backdrop {
  position: absolute; inset: 0;
  background:
    radial-gradient(1100px 480px at 72% -10%, rgba(190, 40, 48, 0.22), transparent 60%),
    radial-gradient(900px 600px at 8% 110%, rgba(140, 30, 38, 0.16), transparent 55%),
    linear-gradient(160deg, #141013 0%, #0b090b 55%, #060506 100%);
}
.ascii-backdrop::before {
  content: ""; position: absolute; left: 0; right: 0; top: 0; height: 6px;
  background: linear-gradient(90deg, #ff2a33, #b3121f 60%, #ff2a33);
}
.ascii-backdrop::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 6px;
  background: linear-gradient(90deg, #b3121f, #ff2a33 60%, #b3121f);
}
.ascii-shell {
  position: absolute; inset: 0; display: flex; gap: 18px; padding: 22px 26px;
  animation: ascii-rise 0.28s cubic-bezier(0.2, 0.9, 0.25, 1);
}
@keyframes ascii-rise {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: none; }
}
.ascii-preview {
  flex: 1; display: flex; flex-direction: column; min-width: 0;
}
.ascii-screen {
  flex: 1; position: relative; min-height: 0;
  border: 1px solid #9aa0ae; border-radius: 3px; background: #000; overflow: hidden;
}
.ascii-screen .editorpanel {
  position: absolute !important; top: 0 !important; left: 0 !important;
  width: 100% !important; height: 100% !important; border: 0 !important; background: #000 !important;
}
.ascii-placeholder {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  color: #777;
}
.ascii-transport {
  flex: 0 0 40px; display: flex; align-items: center; gap: 8px; padding-top: 10px;
}
.ascii-transport button {
  background: #261a1c; border: 1px solid #4a2c30; color: #f0dada;
  font-family: inherit; font-size: 12px; padding: 4px 10px; cursor: pointer; border-radius: 6px;
  transition: background 0.15s ease, transform 0.1s ease;
}
.ascii-transport button:hover { background: #3a2226; }
.ascii-transport button:active { transform: scale(0.96); }
.ascii-time { margin-left: auto; color: #d9a3a8; font-variant-numeric: tabular-nums; }
.ascii-panel {
  flex: 0 0 348px; display: flex; flex-direction: column; min-height: 0;
}
.ascii-pill {
  align-self: stretch; text-align: center;
  background: linear-gradient(180deg, rgba(255, 42, 51, 0.55), rgba(150, 18, 26, 0.55));
  backdrop-filter: blur(6px); border: 1px solid rgba(255, 90, 100, 0.35);
  border-radius: 22px; padding: 12px 0; margin-bottom: 10px;
  font-size: 26px; font-weight: 600; letter-spacing: 0.5px; color: #fff;
  text-shadow: 0 1px 8px rgba(255, 42, 51, 0.5);
}
.ascii-status {
  font-size: 11px; color: #a08b8d; margin-bottom: 8px; min-height: 14px;
}
.ascii-groups {
  flex: 1; overflow-y: auto; background: rgba(26, 20, 22, 0.94);
  border: 1px solid #3a2b2e; border-radius: 4px; padding: 4px 0 12px;
}
.ascii-group { border-bottom: 1px solid #2b2224; }
.ascii-group-head {
  display: flex; align-items: center; gap: 6px; padding: 9px 12px;
  cursor: pointer; user-select: none; font-weight: 600; font-size: 12.5px;
  transition: background 0.15s ease;
}
.ascii-group-head:hover { background: #2b2124; }
.ascii-chevron {
  display: inline-block; width: 12px; color: #c08488;
  transform: rotate(90deg); transition: transform 0.18s ease; font-size: 14px;
}
.ascii-group.closed .ascii-chevron { transform: rotate(0deg); }
.ascii-group-body {
  padding: 2px 12px 10px; display: grid; gap: 7px;
  overflow: hidden; max-height: 1400px; opacity: 1;
  transition: max-height 0.25s ease, opacity 0.2s ease, padding 0.2s ease;
}
.ascii-group.closed .ascii-group-body {
  max-height: 0; opacity: 0; padding-top: 0; padding-bottom: 0;
}
.ascii-row {
  display: grid; grid-template-columns: 118px 1fr auto; align-items: center; gap: 8px;
}
.ascii-row label { color: #d6c9cb; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ascii-row input[type="range"] { width: 100%; accent-color: #e0323c; }
.ascii-row input[type="text"], .ascii-row select {
  background: #141013; border: 1px solid #4a2c30; color: #f0e8e8;
  font-family: inherit; font-size: 12px; padding: 3px 6px; border-radius: 4px; width: 100%;
}
.ascii-row input[type="checkbox"] { width: 15px; height: 15px; accent-color: #e0323c; }
.ascii-row input[type="color"] {
  width: 34px; height: 22px; padding: 0; border: 1px solid #4a2c30; border-radius: 4px;
  background: #141013; cursor: pointer;
}
.ascii-row input:disabled, .ascii-row select:disabled { opacity: 0.45; }
.ascii-value { color: #e88b92; font-variant-numeric: tabular-nums; font-size: 12px; min-width: 44px; text-align: right; }
.ascii-presets { display: grid; gap: 6px; }
.ascii-preset, .ascii-add {
  background: #2b1e21; border: 1px solid #4a3136; color: #f0e8e8;
  font-family: inherit; font-size: 12px; padding: 7px 10px; cursor: pointer; border-radius: 6px;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}
.ascii-preset:hover, .ascii-add:hover { background: #402428; border-color: #8f353d; }
.ascii-preset:active, .ascii-add:active { transform: scale(0.98); }
.ascii-band-title {
  font-size: 11px; font-weight: 600; letter-spacing: 1px; color: #c96a72;
  margin-top: 4px; text-transform: uppercase;
}
.ascii-note { font-size: 11px; color: #8d7d7f; }
.ascii-close {
  position: absolute; top: 14px; right: 16px; width: 30px; height: 30px;
  background: rgba(60, 26, 30, 0.9); border: 1px solid #5a3036; color: #f0e8e8;
  font-size: 14px; cursor: pointer; border-radius: 50%;
  transition: background 0.15s ease, transform 0.1s ease;
}
.ascii-close:hover { background: #6e2126; }
.ascii-close:active { transform: scale(0.94); }
.ascii-groups::-webkit-scrollbar { width: 8px; }
.ascii-groups::-webkit-scrollbar-thumb { background: #4a2c30; border-radius: 4px; }
.ascii-groups::-webkit-scrollbar-track { background: transparent; }

