                texel: { type: "v2", value: new THREE.Vector2(1 / 64, 1 / 64) },
            },
            vertexShader: [
                "varying vec2 vUv;",
                "void main() {",
                "    vUv = uv;",
                "    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);",
                "}",
            ].join("\n"),
            fragmentShader: [
                "uniform sampler2D tDiffuse;",
                "uniform vec3 keyColor;",
                "uniform float blurR;",
                "uniform vec2 texel;",
                "varying vec2 vUv;",
                "void main() {",
