    qTabL[60] = 112.0; qTabL[61] = 100.0; qTabL[62] = 103.0; qTabL[63] = 99.0;
    float qTabC[64];
    qTabC[0] = 17.0; qTabC[1] = 18.0; qTabC[2] = 24.0; qTabC[3] = 47.0;
    qTabC[4] = 99.0; qTabC[5] = 99.0; qTabC[6] = 99.0; qTabC[7] = 99.0;
