text./plugins/openzoid-legacy/tracery-setup.c:
/* Tracery Setup — SaaS dark editor theme (Inter type comes from tracery-font.css). */
.tracery-window {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0; z-index: 1000;
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: #e8eaf0; font-size: 13px;
  animation: tracery-in 0.22s ease-out;
}
@keyframes tracery-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
.tracery-backdrop {
  position: absolute; inset: 0;
  background:
    radial-gradient(1200px 500px at 70% -10%, rgba(120, 130, 160, 0.20), transparent 60%),
    radial-gradient(900px 600px at 10% 110%, rgba(90, 100, 140, 0.14), transparent 55%),
    linear-gradient(160deg, #101014 0%, #0a0a0d 55%, #060608 100%);
}
.tracery-shell {
  position: absolute; inset: 0; display: flex; gap: 18px; padding: 22px 26px;
  animation: tracery-rise 0.28s cubic-bezier(0.2, 0.9, 0.25, 1);
}
@keyframes tracery-rise {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: none; }
}
.tracery-preview {
  flex: 1; display: flex; flex-direction: column; min-width: 0;
}
.tracery-screen {
  flex: 1; position: relative; min-height: 0;
  border: 1px solid #8a8f9e; border-radius: 3px; background: #000; overflow: hidden;
}
.tracery-screen .editorpanel {
  position: absolute !important; top: 0 !important; left: 0 !important;
  width: 100% !important; height: 100% !important; border: 0 !important; background: #000 !important;
}
.tracery-placeholder {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  color: #777;
}
.tracery-placer {
  position: absolute; inset: 0; cursor: crosshair; z-index: 5;
}
.tracery-transport {
  flex: 0 0 40px; display: flex; align-items: center; gap: 8px; padding-top: 10px;
}
.tracery-transport button {
  background: #1d1f26; border: 1px solid #343744; color: #ddd;
  font-family: inherit; font-size: 12px; padding: 4px 10px; cursor: pointer; border-radius: 6px;
  transition: background 0.15s ease, transform 0.1s ease;
}
.tracery-transport button:hover { background: #2a2d38; }
.tracery-transport button:active { transform: scale(0.96); }
.tracery-time { margin-left: auto; color: #9fb6cc; font-variant-numeric: tabular-nums; }
.tracery-panel {
  flex: 0 0 348px; display: flex; flex-direction: column; min-height: 0;
}
.tracery-pill {
  align-self: stretch; text-align: center;
  background: rgba(150, 152, 165, 0.35); backdrop-filter: blur(6px);
  border-radius: 22px; padding: 12px 0; margin-bottom: 10px;
  font-size: 26px; font-weight: 600; letter-spacing: 0.5px; color: #f2f3f7;
}
.tracery-status {
  font-size: 11px; color: #8b90a0; margin-bottom: 8px; min-height: 14px;
}
.tracery-groups {
  flex: 1; overflow-y: auto; background: rgba(22, 23, 29, 0.92);
  border: 1px solid #2b2e38; border-radius: 4px; padding: 4px 0 12px;
}
.tracery-group { border-bottom: 1px solid #23252d; }
.tracery-group-head {
  display: flex; align-items: center; gap: 6px; padding: 9px 12px;
  cursor: pointer; user-select: none; font-weight: 600; font-size: 12.5px;
  transition: background 0.15s ease;
}
.tracery-group-head:hover { background: #20222b; }
.tracery-chevron {
  display: inline-block; width: 12px; color: #9aa0b2;
  transform: rotate(90deg); transition: transform 0.18s ease; font-size: 14px;
}
.tracery-group.closed .tracery-chevron { transform: rotate(0deg); }
.tracery-group-body {
  padding: 2px 12px 10px; display: grid; gap: 7px;
  overflow: hidden; max-height: 1200px; opacity: 1;
  transition: max-height 0.25s ease, opacity 0.2s ease, padding 0.2s ease;
}
.tracery-group.closed .tracery-group-body {
  max-height: 0; opacity: 0; padding-top: 0; padding-bottom: 0;
}
.tracery-row {
  display: grid; grid-template-columns: 118px 1fr auto; align-items: center; gap: 8px;
}
.tracery-row label { color: #c7cbd6; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tracery-row input[type="range"] { width: 100%; accent-color: #7d8bd4; }
.tracery-row input[type="text"], .tracery-row select {
  background: #101218; border: 1px solid #343744; color: #e8eaf0;
  font-family: inherit; font-size: 12px; padding: 3px 6px; border-radius: 4px; width: 100%;
}
.tracery-row input[type="checkbox"] { width: 15px; height: 15px; accent-color: #7d8bd4; }
.tracery-row input[type="color"] {
  width: 34px; height: 22px; padding: 0; border: 1px solid #343744; border-radius: 4px;
  background: #101218; cursor: pointer;
}
.tracery-row input:disabled, .tracery-row select:disabled { opacity: 0.45; }
.tracery-value { color: #8fa3d9; font-variant-numeric: tabular-nums; font-size: 12px; min-width: 44px; text-align: right; }
.tracery-presets { display: grid; gap: 6px; }
.tracery-preset, .tracery-add, .tracery-place {
  background: #23252e; border: 1px solid #383b47; color: #e8eaf0;
  font-family: inherit; font-size: 12px; padding: 7px 10px; cursor: pointer; border-radius: 6px;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}
.tracery-preset:hover, .tracery-add:hover, .tracery-place:hover { background: #2e3140; border-color: #4a4f63; }
.tracery-preset:active, .tracery-add:active, .tracery-place:active { transform: scale(0.98); }
.tracery-place.on { background: #3a4a7d; border-color: #7d8bd4; }
.tracery-tabs { display: flex; gap: 4px; flex-wrap: wrap; }
.tracery-tab {
  background: #1b1d24; border: 1px solid #33363f; color: #aab; font-family: inherit;
  font-size: 11px; padding: 3px 9px; cursor: pointer; border-radius: 20px;
  transition: background 0.15s ease, color 0.15s ease;
}
.tracery-tab.active { background: #3a4a7d; color: #fff; border-color: #7d8bd4; }
.tracery-point-rows { display: grid; gap: 7px; }
.tracery-close {
  position: absolute; top: 14px; right: 16px; width: 30px; height: 30px;
  background: rgba(40, 42, 52, 0.9); border: 1px solid #3a3d49; color: #e8eaf0;
  font-size: 14px; cursor: pointer; border-radius: 50%;
  transition: background 0.15s ease, transform 0.1s ease;
}
.tracery-close:hover { background: #4a2b2b; }
.tracery-close:active { transform: scale(0.94); }
.tracery-groups::-webkit-scrollbar { width: 8px; }
.tracery-groups::-webkit-scrollbar-thumb { background: #343744; border-radius: 4px; }
.tracery-groups::-webkit-scrollbar-track { background: transparent; }

